payload.text:
基于您的需求，我们将引入 **Client ID** 机制。这样画手在建单时指定单主的 ID，单主在连接画手后，系统会自动识别并只展示属于该单主 ID 的内容。

以下是具体的代码更新：

1.  **types.ts**: 在 `Project` 和 `BookingSlot` 中增加 ID 字段。
2.  **utils.ts**: 增加生成 Client ID 的工具函数。
3.  **App.tsx**:
    *   生成并展示单主的 ID。
    *   新建排单时增加“单主 ID”输入框。
    *   单主模式下，根据 ID 自动过滤排单，无需再输入昵称验证。
4.  **components/ScheduleBoard.tsx**: 日程板的权限判断改为基于 ID。

# Updated files:

## types.ts

增加 `targetClientId` 和 `clientId` 字段。

```typescript
export interface Project {
  id: string;
  clientName: string;
  targetClientId?: string; // New: To identify which client owns this project
  description: string;
  startDate: string; // ISO String
  deadline: string; // ISO String
  status: 'pending' | 'in_progress' | 'completed';
}

export interface BookingSlot {
  date: string; // YYYY-MM-DD
  status: 'available' | 'booked' | 'blocked';
  bookedBy?: string;
  clientId?: string; // New: To identify who booked/owns this slot
  note?: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export type ViewMode = 'artist' | 'client';
```

## utils.ts

增加 `generateClientId`。

```typescript
import { Project } from './types';

export const generateArtistId = (): string => {
  return 'ART-' + Math.floor(1000 + Math.random() * 9000);
};

export const generateClientId = (): string => {
  return 'CLI-' + Math.floor(1000 + Math.random() * 9000);
};

export const calculateUrgencyColor = (startDate: string, deadline: string): string => {
  const start = new Date(startDate).getTime();
  const end = new Date(deadline).getTime();
  const now = new Date().getTime();

  if (now > end) return 'bg-rose-900 text-white'; // Overdue

  const totalDuration = end - start;
  const timeLeft = end - now;
  const hoursLeft = timeLeft / (1000 * 60 * 60);

  // Critical: Less than 6 hours
  if (hoursLeft < 6) {
    return 'bg-gradient-to-br from-rose-600 to-red-700 text-white animate-pulse';
  }

  // Warning: Less than 24 hours
  if (hoursLeft < 24) {
    return 'bg-gradient-to-br from-orange-400 to-rose-500 text-white';
  }

  // Caution: Less than 25% time remaining
  const percentageLeft = timeLeft / totalDuration;
  if (percentageLeft < 0.25) {
    return 'bg-gradient-to-br from-yellow-300 to-orange-400 text-slate-900';
  }

  // Safe: Just started or plenty of time
  return 'bg-gradient-to-br from-emerald-400 to-teal-500 text-white';
};

export const getStatusLabel = (hoursLeft: number): string => {
  if (hoursLeft < 0) return '已截稿';
  if (hoursLeft < 6) return '极度紧急';
  if (hoursLeft < 24) return '即将截止';
  if (hoursLeft < 72) return '需赶工';
  return '正常进行';
};

export const formatDate = (isoString: string): string => {
  return new Date(isoString).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
};
```

## App.tsx

**主要变更点**：
1.  **Client ID 管理**：初始化 `myClientId`，并在单主模式首页展示，支持一键复制。
2.  **新建排单升级**：画手新建排单时，现在必须输入 `targetClientId`。
3.  **自动过滤**：单主连接画手后，系统自动筛选 `project.targetClientId === myClientId` 的项目，无需手动确认身份。
4.  **UI 优化**：在单主首页增加了醒目的 ID 展示卡片。

```tsx
import React, { useState, useEffect } from 'react';
import { Project, BookingSlot, ViewMode } from './types';
import ProjectCard from './components/ProjectCard';
import ScheduleBoard from './components/ScheduleBoard';
import { analyzeSchedule } from './services/geminiService';
import { generateArtistId, generateClientId } from './utils';
import { 
  Layout, 
  Plus, 
  CalendarDays, 
  Paintbrush, 
  Sparkles, 
  X,
  Search,
  Copy,
  UserCircle2,
  LogOut,
  Fingerprint
} from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'projects' | 'schedule'>('projects');
  const [viewMode, setViewMode] = useState<ViewMode>('artist');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showAI, setShowAI] = useState(false);

  // Identity State
  const [myArtistId, setMyArtistId] = useState<string>('');
  const [myClientId, setMyClientId] = useState<string>(''); // NEW: Client ID
  const [searchId, setSearchId] = useState('');
  const [connectedArtistId, setConnectedArtistId] = useState<string | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [bookings, setBookings] = useState<BookingSlot[]>([]);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // New Project Form State
  const [newProject, setNewProject] = useState<Partial<Project>>({
    clientName: '',
    targetClientId: '', // NEW
    description: '',
    startDate: '',
    deadline: ''
  });

  // Initialization: Load or Create IDs
  useEffect(() => {
    // Artist ID
    const storedArtistId = localStorage.getItem('artflow_artist_id');
    if (storedArtistId) {
      setMyArtistId(storedArtistId);
    } else {
      const newId = generateArtistId();
      localStorage.setItem('artflow_artist_id', newId);
      setMyArtistId(newId);
    }

    // Client ID
    const storedClientId = localStorage.getItem('artflow_client_id');
    if (storedClientId) {
      setMyClientId(storedClientId);
    } else {
      const newId = generateClientId();
      localStorage.setItem('artflow_client_id', newId);
      setMyClientId(newId);
    }
  }, []);

  // Determine current active Data Source ID based on View Mode
  const currentDataId = viewMode === 'artist' ? myArtistId : connectedArtistId;

  // Load Data when ID or Mode changes
  useEffect(() => {
    if (!currentDataId) {
      setProjects([]);
      setBookings([]);
      return;
    }

    const storedProjects = localStorage.getItem(`artflow_data_${currentDataId}_projects`);
    const storedBookings = localStorage.getItem(`artflow_data_${currentDataId}_bookings`);

    setProjects(storedProjects ? JSON.parse(storedProjects) : []);
    setBookings(storedBookings ? JSON.parse(storedBookings) : []);
  }, [currentDataId, viewMode]);

  // Persist Data (Simulate Backend)
  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_projects`, JSON.stringify(projects));
    }
  }, [projects, currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_bookings`, JSON.stringify(bookings));
    }
  }, [bookings, currentDataId, viewMode]);

  const handleSearchArtist = () => {
    if (!searchId.trim()) return;

    if (searchId === myArtistId) {
       setConnectedArtistId(searchId);
       return;
    }

    const targetProjects = localStorage.getItem(`artflow_data_${searchId}_projects`);
    // Ideally we verify if it exists, but for local simulation we act as if it might
    if (targetProjects) {
      setConnectedArtistId(searchId);
    } else {
      if(confirm(`未找到画手 ${searchId} 的本地记录。是否仍要连接（假设其存在）？`)) {
         setConnectedArtistId(searchId);
      }
    }
  };

  const handleDisconnect = () => {
    setConnectedArtistId(null);
    setSearchId('');
  };

  const handleAddProject = () => {
    if (!newProject.clientName || !newProject.startDate || !newProject.deadline) return;

    const project: Project = {
      id: Date.now().toString(),
      clientName: newProject.clientName!,
      targetClientId: newProject.targetClientId || '', // Save the ID
      description: newProject.description || 'No description',
      startDate: newProject.startDate!,
      deadline: newProject.deadline!,
      status: 'pending'
    };

    setProjects([...projects, project]);
    setNewProject({ clientName: '', targetClientId: '', description: '', startDate: '', deadline: '' });
    setShowAddModal(false);
  };

  const handleCompleteProject = (id: string) => {
    if (viewMode === 'client') return;
    setProjects(projects.map(p => p.id === id ? { ...p, status: 'completed' } : p));
  };

  const handleDeleteProject = (id: string) => {
    if (viewMode === 'client') return;
    if(confirm('Delete this project?')) {
        setProjects(projects.filter(p => p.id !== id));
    }
  };

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    setAiResponse('');

    const response = await analyzeSchedule(projects, bookings, aiQuery);

    setAiResponse(response);
    setIsAiLoading(false);
  };

  const copyText = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    alert(`${label} 已复制到剪贴板`);
  };

  // Switch Mode Handler
  const toggleViewMode = () => {
    const newMode = viewMode === 'artist' ? 'client' : 'artist';
    setViewMode(newMode);
    // Reset client state when switching away
    if (newMode === 'artist') {
      handleDisconnect();
    }
  };

  // Filter projects based on mode
  const visibleProjects = viewMode === 'artist' 
    ? projects 
    : projects.filter(p => {
        // Strict ID check for Client Mode
        return p.targetClientId === myClientId;
    });

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 flex flex-col">

      {/* Mobile Sticky Header */}
      <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-5 py-3 shadow-sm transition-all">
        <div className="flex justify-between items-center mb-3 md:mb-0">
          <div className="flex items-center gap-2.5">
            <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-2 rounded-xl shadow-indigo-200 shadow-lg">
              <Paintbrush size={18} />
            </div>
            <h1 className="text-lg font-bold text-slate-800 tracking-tight hidden md:block">
              ArtFlow
            </h1>
          </div>

          <div className="flex items-center gap-3">
             {viewMode === 'artist' && (
                <button 
                  onClick={() => setShowAI(!showAI)}
                  className={`p-2 rounded-full transition-colors ${showAI ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-100 text-slate-400'}`}
                >
                  <Sparkles size={20} />
                </button>
             )}
            <button 
                onClick={toggleViewMode}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-full transition-all border ${viewMode === 'artist' ? 'bg-slate-800 text-white border-slate-800' : 'bg-indigo-600 text-white border-indigo-600'}`}
            >
                {viewMode === 'artist' ? <><Paintbrush size={12}/> 画手模式</> : <><UserCircle2 size={14}/> 单主模式</>}
            </button>
          </div>
        </div>

        {/* Dynamic Sub-Header Area */}
        <div className="w-full">
           {viewMode === 'artist' ? (
             <div className="flex items-center justify-between bg-slate-50 rounded-lg p-2 border border-slate-100">
               <span className="text-xs text-slate-500 font-medium px-2">我的画手ID: <span className="text-slate-900 font-bold font-mono">{myArtistId}</span></span>
               <button onClick={() => copyText(myArtistId, 'Artist ID')} className="p-1.5 hover:bg-white rounded-md text-slate-400 hover:text-indigo-600 transition-colors">
                 <Copy size={14} />
               </button>
             </div>
           ) : (
             <div className="flex gap-2">
               {!connectedArtistId ? (
                 <>
                  <div className="relative flex-1">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      value={searchId}
                      onChange={(e) => setSearchId(e.target.value)}
                      placeholder="搜索画手 ID (如: ART-1234)"
                      className="w-full bg-slate-100 border-none rounded-lg pl-9 pr-4 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                    />
                  </div>
                  <button 
                    onClick={handleSearchArtist}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap"
                  >
                    连接
                  </button>
                 </>
               ) : (
                 <div className="flex items-center justify-between w-full bg-indigo-50 rounded-lg p-2 border border-indigo-100">
                    <span className="text-xs text-indigo-800 font-medium px-2 flex items-center gap-1">
                      <span className="opacity-60">已连接:</span> 
                      <span className="font-bold">{connectedArtistId}</span>
                    </span>
                    <button 
                      onClick={handleDisconnect}
                      className="flex items-center gap-1 bg-white px-2 py-1 rounded text-[10px] font-bold text-slate-500 shadow-sm"
                    >
                      <LogOut size={10} /> 退出
                    </button>
                 </div>
               )}
             </div>
           )}
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 w-full max-w-lg mx-auto p-5 pb-32">

        {/* Client Mode - Initial State (Show ID) */}
        {viewMode === 'client' && !connectedArtistId && (
           <div className="flex flex-col items-center justify-center mt-10 animate-fade-in">
              {/* My ID Card */}
              <div className="w-full bg-white rounded-2xl shadow-xl shadow-slate-100 border border-slate-100 p-6 mb-8 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-20 h-20 bg-indigo-50 rounded-bl-full -mr-10 -mt-10"></div>
                <div className="flex items-center gap-3 mb-2">
                  <Fingerprint className="text-indigo-600" size={24} />
                  <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider">我的单主 ID</h3>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-3xl font-black text-slate-800 tracking-tight">{myClientId}</span>
                  <button 
                    onClick={() => copyText(myClientId, '单主 ID')}
                    className="bg-indigo-50 text-indigo-600 p-2 rounded-lg hover:bg-indigo-100 transition-colors"
                    title="复制"
                  >
                    <Copy size={18} />
                  </button>
                </div>
                <p className="text-xs text-slate-400 mt-3 leading-relaxed">
                  请将此 ID 发送给画手。画手为您新建排单时填入此 ID，您连接后即可同步看到进度。
                </p>
              </div>

              <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4 text-slate-300">
                <Search size={32} />
              </div>
              <p className="text-slate-400 text-sm text-center max-w-[200px]">
                在上方搜索框输入画手 ID 开始连接
              </p>
           </div>
        )}

        {/* Main Content (Artist or Connected Client) */}
        {(viewMode === 'artist' || connectedArtistId) && (
          <>
            {/* AI Assistant Card (Artist Only) */}
            {viewMode === 'artist' && showAI && (
              <div className="mb-6 bg-white border border-indigo-100 rounded-2xl p-4 shadow-lg shadow-indigo-100/50 animate-fade-in">
                {/* AI Card Content */}
                <div className="flex justify-between items-center mb-3">
                  <h3 className="font-bold text-indigo-900 flex items-center gap-2 text-sm">
                    <Sparkles size={14} className="text-indigo-500" /> 智能助理
                  </h3>
                  <button onClick={() => setShowAI(false)} className="text-slate-400 hover:text-slate-600">
                    <X size={16} />
                  </button>
                </div>

                <div className="bg-slate-50 rounded-xl p-3 min-h-[60px] mb-3 text-sm text-slate-600 leading-relaxed">
                  {isAiLoading ? (
                    <div className="flex items-center gap-2 text-indigo-500">
                      <div className="animate-spin h-3 w-3 border-2 border-indigo-500 border-t-transparent rounded-full"></div>
                      正在思考中...
                    </div>
                  ) : (
                    aiResponse || "你好！我是你的排单助手。可以问我关于档期安排、截稿压力的问题。"
                  )}
                </div>

                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={aiQuery}
                    onChange={(e) => setAiQuery(e.target.value)}
                    placeholder="问问我：下周还能接急单吗？"
                    className="flex-1 text-sm rounded-lg bg-white border border-slate-200 px-3 py-2.5 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                    onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()}
                  />
                  <button 
                    onClick={handleAiAsk}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold shadow-md shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all"
                  >
                    发送
                  </button>
                </div>
              </div>
            )}

            {/* Content Views */}
            {activeTab === 'projects' && (
              <div className="animate-fade-in space-y-5">
                <div className="flex justify-between items-end px-1">
                   <div>
                     <h2 className="text-xl font-bold text-slate-800">
                       {viewMode === 'artist' ? '我的排单' : '我的订单'}
                     </h2>
                     <p className="text-slate-400 text-xs mt-1">
                       {viewMode === 'artist' ? '关注颜色变化，避免延期' : `仅展示关联 ID: ${myClientId} 的项目`}
                     </p>
                   </div>
                   {/* Desktop Add Button (Artist Only) */}
                   {viewMode === 'artist' && (
                     <button 
                       onClick={() => setShowAddModal(true)}
                       className="hidden md:flex bg-slate-900 text-white px-4 py-2 rounded-full text-sm font-bold shadow-lg hover:scale-105 transition-transform gap-2 items-center"
                     >
                       <Plus size={16} /> 新建
                     </button>
                   )}
                </div>

                <div className="space-y-3">
                  {visibleProjects.filter(p => p.status !== 'completed').length === 0 && (
                    <div className="flex flex-col items-center justify-center py-16 text-slate-400 bg-white rounded-2xl border border-dashed border-slate-200">
                      <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center mb-3">
                        <Paintbrush size={20} className="opacity-50" />
                      </div>
                      <p className="text-sm font-medium">暂无进行中的约稿</p>
                      {viewMode === 'client' && <p className="text-xs opacity-70 mt-1 max-w-[200px] text-center">如果您确认有单，请确认画手已正确填入您的 ID: {myClientId}</p>}
                    </div>
                  )}
                  {visibleProjects
                    .sort((a, b) => new Date(a.deadline).getTime() - new Date(b.deadline).getTime())
                    .map(project => (
                      <ProjectCard 
                        key={project.id} 
                        project={project} 
                        onComplete={handleCompleteProject}
                        onDelete={handleDeleteProject}
                        readOnly={viewMode === 'client'}
                      />
                  ))}

                  {visibleProjects.some(p => p.status === 'completed') && (
                    <div className="mt-8">
                      <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-4 px-1">已完成记录</h3>
                      <div className="space-y-3 opacity-60 hover:opacity-100 transition-opacity">
                        {visibleProjects
                          .filter(p => p.status === 'completed')
                          .map(project => (
                            <ProjectCard 
                              key={project.id} 
                              project={project} 
                              onComplete={handleCompleteProject}
                              onDelete={handleDeleteProject}
                              readOnly={viewMode === 'client'}
                            />
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === 'schedule' && (
              <div className="animate-fade-in">
                 <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                    <ScheduleBoard 
                      bookings={bookings} 
                      projects={projects} 
                      mode={viewMode}
                      onUpdateBookings={setBookings}
                      currentClientId={viewMode === 'client' ? myClientId : undefined}
                      currentClientName={viewMode === 'client' ? '我' : undefined}
                    />
                 </div>
              </div>
            )}
          </>
        )}

      </main>

      {/* Mobile Bottom Navigation Bar */}
      {(viewMode === 'artist' || connectedArtistId) && (
        <nav className="fixed bottom-0 left-0 w-full bg-white border-t border-slate-100 pb-[env(safe-area-inset-bottom)] z-40 shadow-[0_-4px_20px_rgba(0,0,0,0.03)]">
          <div className="flex justify-between items-center px-6 h-16 md:hidden">
            {/* Projects Tab */}
            <button 
              onClick={() => setActiveTab('projects')}
              className={`flex-1 flex flex-col items-center justify-center gap-1 h-full active:scale-90 transition-transform ${activeTab === 'projects' ? 'text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
            >
              <Layout size={22} strokeWidth={activeTab === 'projects' ? 2.5 : 2} />
              <span className="text-[10px] font-medium">列表</span>
            </button>

            {/* Center FAB (Artist Only) */}
            {viewMode === 'artist' ? (
              <div className="relative -top-5">
                <button 
                  onClick={() => setShowAddModal(true)}
                  className="w-14 h-14 bg-slate-900 rounded-full flex items-center justify-center text-white shadow-xl shadow-slate-300 active:scale-90 transition-transform border-4 border-slate-50"
                >
                  <Plus size={28} strokeWidth={2.5} />
                </button>
              </div>
            ) : (
              <div className="w-8"></div> // Spacer for layout balance
            )}

            {/* Schedule Tab */}
            <button 
              onClick={() => setActiveTab('schedule')}
              className={`flex-1 flex flex-col items-center justify-center gap-1 h-full active:scale-90 transition-transform ${activeTab === 'schedule' ? 'text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
            >
              <CalendarDays size={22} strokeWidth={activeTab === 'schedule' ? 2.5 : 2} />
              <span className="text-[10px] font-medium">排期</span>
            </button>
          </div>

          {/* Desktop Nav Fallback */}
          <div className="hidden md:flex justify-center gap-8 py-4 bg-white border-t border-slate-200">
             <button 
              onClick={() => setActiveTab('projects')}
              className={`px-6 py-2 rounded-xl font-bold transition-all ${activeTab === 'projects' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              排单列表
            </button>
             <button 
              onClick={() => setActiveTab('schedule')}
              className={`px-6 py-2 rounded-xl font-bold transition-all ${activeTab === 'schedule' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              排期日历
            </button>
          </div>
        </nav>
      )}

      {/* Add Project - Mobile Bottom Sheet / Desktop Modal */}
      {showAddModal && viewMode === 'artist' && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end md:justify-center md:items-center bg-slate-900/40 backdrop-blur-sm animate-fade-in">
          {/* Dismiss Area */}
          <div className="absolute inset-0" onClick={() => setShowAddModal(false)}></div>

          <div className="relative bg-white w-full md:w-[400px] md:rounded-3xl rounded-t-3xl shadow-2xl animate-slide-up overflow-hidden flex flex-col max-h-[90vh]">

            {/* Handle for mobile feeling */}
