3.  `isMySlot` 逻辑：如果 `BookingSlot.clientId` 匹配 `currentClientId`，则视为“我的时间块”，允许查看详情，否则隐藏。

```tsx
import React, { useState } from 'react';
import { BookingSlot, ViewMode, Project } from '../types';
import { ShieldBan, RefreshCw, Check, Lock } from 'lucide-react';

interface ScheduleBoardProps {
  bookings: BookingSlot[];
  projects: Project[];
  mode: ViewMode;
  onUpdateBookings: (bookings: BookingSlot[]) => void;
  currentClientId?: string;
  currentClientName?: string;
}

const ScheduleBoard: React.FC<ScheduleBoardProps> = ({ 
  bookings, 
  projects, 
  mode, 
  onUpdateBookings,
  currentClientId,
  currentClientName 
}) => {
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [bookingNote, setBookingNote] = useState('');

  // Generate next 14 days (2 weeks)
  const getDays = () => {
    const days = [];
    for (let i = 0; i < 21; i++) { // Show 3 weeks for better vertical fill
      const d = new Date();
      d.setDate(d.getDate() + i);
      days.push(d.toISOString().split('T')[0]);
    }
    return days;
  };

  const days = getDays();
  const getSlot = (date: string) => bookings.find(b => b.date === date);

  // Helper: Check if the slot belongs to the current viewer (Client mode)
  const isMySlot = (slot?: BookingSlot) => {
    if (!slot) return false;
    if (mode === 'artist') return true; // Artist owns everything

    // Check ID match (Strong check)
    if (currentClientId && slot.clientId === currentClientId) return true;

    // Check manual booking name (Legacy check)
    if (slot.bookedBy && currentClientName && slot.bookedBy.toLowerCase() === currentClientName.toLowerCase()) return true;

    return false;
  };

  const handleDayClick = (date: string) => {
    const slot = getSlot(date);

    if (mode === 'artist') {
      const newBookings = [...bookings];
      const index = newBookings.findIndex(b => b.date === date);

      if (index >= 0) {
        if (newBookings[index].status === 'blocked') {
          newBookings.splice(index, 1);
        } else {
          if(confirm("该日期已有预约，确定要清除吗？")) {
             newBookings.splice(index, 1);
          }
        }
      } else {
        newBookings.push({ date, status: 'blocked' });
      }
      onUpdateBookings(newBookings);
    } else {
      if (slot?.status === 'blocked' || slot?.status === 'booked') return;
      setSelectedDate(date);
      setBookingNote('');
    }
  };

  const handleClientBook = () => {
    if (!selectedDate) return;

    const newBookings = [...bookings, {
      date: selectedDate,
      status: 'booked' as const,
      bookedBy: currentClientName || 'Client',
      clientId: currentClientId, // Store ID
      note: bookingNote
    }];

    onUpdateBookings(newBookings);
    setSelectedDate(null);
    alert('预约申请已提交！');
  };

  const syncProjectsToSchedule = () => {
    const newBookings = [...bookings];
    let count = 0;

    projects.forEach(p => {
      if (p.status === 'completed') return;
      const start = new Date(p.startDate);
      const end = new Date(p.deadline);

      for(let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
        const isoDate = d.toISOString().split('T')[0];
        // If slot is free, block it with project info
        if (!newBookings.find(b => b.date === isoDate)) {
           newBookings.push({ 
             date: isoDate, 
             status: 'blocked', 
             note: `Project: ${p.clientName}`,
             clientId: p.targetClientId // Sync the Client ID to the slot
           });
           count++;
        }
      }
    });

    onUpdateBookings(newBookings);
    alert(`已自动同步，锁定了 ${count} 个日期。`);
  };

  return (
    <div className="p-5">
      <div className="flex justify-between items-center mb-6">
        <div>
           <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            {mode === 'artist' ? '排期管理' : '预约排期'}
          </h2>
          <p className="text-xs text-slate-400 mt-0.5">
            {mode === 'artist' ? '点击日期切换锁定状态' : '灰色为不可选，白色为可选'}
          </p>
        </div>

        {mode === 'artist' && (
          <button 
            onClick={syncProjectsToSchedule}
            className="flex flex-col items-center justify-center bg-indigo-50 text-indigo-600 w-10 h-10 rounded-full active:scale-90 transition-transform"
            title="同步进行中项目"
          >
            <RefreshCw size={18} />
          </button>
        )}
      </div>

      <div className="grid grid-cols-7 gap-1.5 mb-2">
        {['日', '一', '二', '三', '四', '五', '六'].map(d => (
            <div key={d} className="text-center text-[10px] font-bold text-slate-300 uppercase tracking-wide py-1">{d}</div>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-1.5">
        {days.map(date => {
          const slot = getSlot(date);
          const dateObj = new Date(date);
          const dayNum = dateObj.getDate();
          const isToday = new Date().toISOString().split('T')[0] === date;
          const isMine = isMySlot(slot);

          let bgClass = 'bg-white border-slate-100 text-slate-700'; // Available
          let content = <span className={`text-sm font-medium ${isToday ? 'text-indigo-600 font-bold' : ''}`}>{dayNum}</span>;

          if (slot?.status === 'blocked') {
             // Blocked logic
             if (mode === 'client' && !isMine) {
                // Anonymous block for other clients
                bgClass = 'bg-slate-100 border-slate-100 text-slate-300';
                content = <Lock size={14} className="opacity-30" />; 
             } else {
                // Artist view or Client's own slot
                bgClass = 'bg-slate-100 border-slate-100 text-slate-400';
                content = <ShieldBan size={14} className="opacity-40" />;
             }
          } else if (slot?.status === 'booked') {
             // Booked logic
             if (mode === 'client' && !isMine) {
                // Anonymous booked for other clients
                bgClass = 'bg-slate-100 border-slate-100 text-slate-300';
                content = <Lock size={14} className="opacity-30" />;
             } else {
                // Artist view or Client's own slot
                bgClass = 'bg-indigo-600 border-indigo-600 text-white shadow-md shadow-indigo-200';
                content = <Check size={16} strokeWidth={3} />;
             }
          }

          if (selectedDate === date) {
            bgClass = 'ring-2 ring-indigo-500 ring-offset-2 bg-indigo-500 text-white z-10';
            content = <span className="font-bold">{dayNum}</span>;
          }

          return (
            <div 
              key={date}
              onClick={() => handleDayClick(date)}
              className={`aspect-[4/5] rounded-lg border flex items-center justify-center relative transition-all duration-200 active:scale-95 ${bgClass}`}
            >
              {content}
            </div>
          );
        })}
      </div>

      {mode === 'client' && selectedDate && (
        <div className="mt-6 animate-slide-up bg-slate-50 p-4 rounded-2xl border border-slate-100">
          <div className="flex items-center gap-2 mb-3 text-sm font-bold text-slate-700">
            <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
            预约: {selectedDate}
          </div>
          <div className="flex gap-2">
            <input 
              type="text" 
              placeholder="备注 / 需求 (可选)"
              value={bookingNote}
              onChange={(e) => setBookingNote(e.target.value)}
              className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500"
            />
            <button 
              onClick={handleClientBook}
              className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-sm font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-colors"
            >
              提交
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ScheduleBoard;

