```typescript
import { Project } from './types';

export const generateArtistId = (): string => {
  return 'ART-' + Math.floor(1000 + Math.random() * 9000);
};

export const generateClientId = (): string => {
  return 'CLI-' + Math.floor(1000 + Math.random() * 9000);
};

export const calculateUrgencyColor = (startDate: string, deadline: string): string => {
  const end = new Date(deadline).getTime();
  const now = new Date().getTime();

  if (now > end) return 'bg-slate-100 border border-slate-200 text-slate-500'; // Overdue / Completed style

  const timeLeft = end - now;
  const daysLeft = timeLeft / (1000 * 60 * 60 * 24);

  // 1-2 days or less -> Red (Soft/Restrained)
  if (daysLeft <= 2) {
    return 'bg-rose-50 border border-rose-100 text-rose-900';
  }

  // 3-5 days -> Orange (Soft/Restrained)
  if (daysLeft <= 5) {
    return 'bg-orange-50 border border-orange-100 text-orange-900';
  }

  // Rest -> Green (Soft/Restrained)
  return 'bg-emerald-50 border border-emerald-100 text-emerald-900';
};

// New helper for the thin lines in the calendar
export const getProjectLineColor = (startDate: string, deadline: string): string => {
  const end = new Date(deadline).getTime();
  const now = new Date().getTime();

  if (now > end) return 'bg-slate-200'; 

  const timeLeft = end - now;
  const daysLeft = timeLeft / (1000 * 60 * 60 * 24);

  // Use softer 300 shades to match the "restrained" aesthetic while remaining visible
  if (daysLeft <= 2) {
    return 'bg-rose-300';
  }

  if (daysLeft <= 5) {
    return 'bg-orange-300';
  }

  return 'bg-emerald-300';
};

export const getStatusLabel = (startDate: string, deadline: string): string => {
  const end = new Date(deadline).getTime();
  const now = new Date().getTime();
  const timeLeft = end - now;
  const daysLeft = timeLeft / (1000 * 60 * 60 * 24);

  if (now > end) return '已截稿';
  if (daysLeft <= 2) return '即将截止';
  if (daysLeft <= 5) return '需赶工';
  return '进行中';
};

export const formatDate = (isoString: string): string => {
  return new Date(isoString).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
};
