import React, { useState } from 'react';
import { BookingSlot, ViewMode, Project } from '../types';
import { ShieldBan, Check, Lock } from 'lucide-react';
import { getProjectLineColor } from '../utils';

interface ScheduleBoardProps {
  bookings: BookingSlot[];
  projects: Project[];
  mode: ViewMode;
  onUpdateBookings: (bookings: BookingSlot[]) => void;
  currentClientId?: string;
  currentClientName?: string;
}

const ScheduleBoard: React.FC<ScheduleBoardProps> = ({ 
  bookings, 
  projects, 
  mode, 
  onUpdateBookings,
  currentClientId,
  currentClientName 
}) => {
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [bookingNote, setBookingNote] = useState('');

  // Helper to get local YYYY-MM-DD string to avoid UTC shifts
  const getLocalYYYYMMDD = (d: Date) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // Generate next 21 days
  const getDays = () => {
    const days = [];
    const today = new Date();
    for (let i = 0; i < 21; i++) {
      const d = new Date(today);
      d.setDate(today.getDate() + i);
      days.push(getLocalYYYYMMDD(d));
    }
    return days;
  };

  const days = getDays();
  const getSlot = (date: string) => bookings.find(b => b.date === date);

  // Get all active projects that overlap with this date
  const getProjectsOnDate = (dateStr: string) => {
    const targetDate = new Date(dateStr + 'T00:00:00'); 

    const activeProjects = projects.filter(p => {
       if (p.status === 'completed') return false;

       // Filter based on View Mode
       if (mode === 'client' && p.targetClientId !== currentClientId) return false;

       const start = new Date(p.startDate);
       const end = new Date(p.deadline);

       // Normalize start/end to start-of-day for inclusive comparison
       const startDay = new Date(start.getFullYear(), start.getMonth(), start.getDate());
       const endDay = new Date(end.getFullYear(), end.getMonth(), end.getDate());

       return targetDate >= startDay && targetDate <= endDay;
    });

    // Sort by start date to keep visual consistency (lines don't jump around)
    return activeProjects.sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
  };

  // Helper: Check if the slot belongs to the current viewer (Client mode)
  const isMySlot = (clientId?: string, bookedBy?: string) => {
    if (mode === 'artist') return true; // Artist owns everything

    // Check ID match (Strong check)
    if (currentClientId && clientId === currentClientId) return true;

    // Check manual booking name (Legacy check)
    if (bookedBy && currentClientName && bookedBy.toLowerCase() === currentClientName.toLowerCase()) return true;

