                         <div className={`w-2 h-2 rounded-full ${selectedTimeBoxes.includes('evening') ? 'bg-fuchsia-500' : 'bg-transparent'}`}></div>
                     </div>
                     <div className={`flex-1 p-5 rounded-2xl border transition-all ${selectedTimeBoxes.includes('evening') ? 'bg-gradient-to-r from-indigo-50 to-white border-indigo-100 shadow-md' : 'bg-white border-slate-100 text-slate-400'}`}>
                         <div className="flex items-center justify-between">
                             <div className="flex items-center gap-3">
                                 <div className={`p-2 rounded-full ${selectedTimeBoxes.includes('evening') ? 'bg-indigo-100 text-indigo-500' : 'bg-slate-50'}`}>
                                     <Moon size={20} />
                                 </div>
                                 <span className="font-bold text-lg">晚 Evening</span>
                             </div>
                             {selectedTimeBoxes.includes('evening') && <Check size={20} className="text-indigo-500" />}
