                                 <span className="text-xs font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-lg">
                                     {selectedActualHours.length} 小时
                                 </span>
                             </div>
                             <p className="text-[10px] text-slate-400 mt-1">
                                 点选你实际专注的时间段，对比左侧计划。
                             </p>
                         </div>

                         <div className="space-y-1">
                             {timeSlots.map((slot) => {
                                 const isSelected = selectedActualHours.includes(slot.id);
                                 return (
                                     <div 
                                        key={slot.id}
                                        onClick={() => toggleActualHour(slot.id)}
                                        className={`flex items-center gap-3 p-3 rounded-xl cursor-pointer transition-all select-none ${isSelected ? 'bg-emerald-50 border border-emerald-100' : 'hover:bg-slate-50 border border-transparent'}`}
                                     >
                                         <div className={`text-xs font-mono font-bold w-12 text-right ${isSelected ? 'text-emerald-600' : 'text-slate-400'}`}>
                                             {slot.label}
                                         </div>
                                         <div className={`flex-1 h-8 rounded-lg flex items-center px-3 text-xs font-bold transition-all ${isSelected ? 'bg-emerald-500 text-white shadow-sm' : 'bg-slate-100 text-slate-300'}`}>
                                             {isSelected ? 'Focus Work' : ''}
                                         </div>
                                         {slot.isNextDay && !isSelected && <span className="text-[10px] text-slate-300">+1</span>}
                                     </div>
                                 );
                             })}
                         </div>
                     </div>
                 )}
             </div>

             {/* Bottom Action (Only for Comparison now) */}
             {isComparison && (
                <div className="fixed bottom-0 left-0 w-full bg-gradient-to-t from-white via-white to-transparent pt-10 pb-12 px-6 z-30 pointer-events-none">
