```tsx
import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool } from 'lucide-react';
import { PlannerStage, Project } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[]; // Receive projects to find sync match
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [] }) => {
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');

  // Sync State
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);

  // 'setup' = arranging, 'time-entry' = duration, 'finished' = summary, 'time-boxing' = daily planning, 
  // 'pre-comparison-confirm' = preview selection before done list, 'daily-comparison' = actual vs plan
  const [planningStep, setPlanningStep] = useState<'setup' | 'time-entry' | 'finished' | 'time-boxing' | 'pre-comparison-confirm' | 'daily-comparison'>('setup');

  // Index of the stage currently being edited (starts from bottom)
  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});

  // Time Boxing State
  const [currentBoxStageIndex, setCurrentBoxStageIndex] = useState(0);
  const [selectedTimeBoxes, setSelectedTimeBoxes] = useState<string[]>([]);

  // Actual Execution State
  const [selectedActualHours, setSelectedActualHours] = useState<string[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // Helper to calculate duration in days
  const getDaysDiff = (startStr: string, endStr: string) => {
    const start = new Date(startStr).getTime();
    const end = new Date(endStr).getTime();
    return Math.max(0, Math.ceil((end - start) / (1000 * 60 * 60 * 24)));
  };

  const addDays = (dateStr: string, daysToAdd: number) => {
    const date = new Date(dateStr);
    date.setDate(date.getDate() + daysToAdd);
    return date;
  };

  const totalAvailableDays = syncedProject ? getDaysDiff(syncedProject.startDate, syncedProject.deadline) : 0;
  const currentPlannedDays = Object.values(estimates).reduce<number>((a, b) => a + Number(b), 0);
  const isOverBudget = syncedProject ? currentPlannedDays > totalAvailableDays : false;

  // Generate hours from 09:00 to 03:00 (+1 day)
  const generateTimeSlots = () => {
      const slots = [];
      for (let i = 9; i <= 27; i++) {
          const hour = i % 24;
          const label = `${hour.toString().padStart(2, '0')}:00`;
          const isNextDay = i >= 24;
          slots.push({ id: `h-${i}`, value: i, label, isNextDay, fullLabel: isNextDay ? `次日 ${label}` : label });
      }
      return slots;
  };
  const timeSlots = generateTimeSlots();

  const handleDragStart = (index: number) => {
    dragItem.current = index;
  };

  const handleDragEnter = (index: number) => {
    dragOverItem.current = index;
  };

  const handleDragEnd = () => {
    if (dragItem.current === null || dragOverItem.current === null) return;
    const copyListItems = [...stages];
    const dragItemContent = copyListItems[dragItem.current];
    copyListItems.splice(dragItem.current, 1);
    copyListItems.splice(dragOverItem.current, 0, dragItemContent);
    dragItem.current = null;
    dragOverItem.current = null;
    setStages(copyListItems);
  };

  const handleConfirmAdd = () => {
    if (newStageTitle.trim()) {
        const newStage: PlannerStage = { 
            id: Date.now().toString(), 
            title: newStageTitle.trim(), 
            isDeletable: true 
        };
        setStages([newStage, ...stages]);
        setNewStageTitle('');
        setIsAdding(false);
    }
  };

  const deleteStage = (index: number) => {
      if(confirm('确定删除此阶段吗?')) {
          const newStages = [...stages];
          newStages.splice(index, 1);
          setStages(newStages);
      }
  };

  const handleSyncProject = () => {
      if(!syncId.trim()) return;
      const found = projects.find(p => p.id === syncId.trim());
      if(found) {
          setSyncedProject(found);
          setShowSyncInput(false);
          setSyncId('');
      } else {
          alert('未找到该 ID 对应的排单，请检查是否输入正确。');
      }
  };

  const startConfiguration = () => {
      setPlanningStep('time-entry');
      setActiveTimeIndex(stages.length - 1);
      setCurrentInputTime('');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;

      const currentStage = stages[activeTimeIndex];
      setEstimates({ ...estimates, [currentStage.id]: currentInputTime });

      if (activeTimeIndex > 0) {
          setActiveTimeIndex(activeTimeIndex - 1);
          setCurrentInputTime('');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleTimeInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      if (/^\d*\.?\d*$/.test(val)) {
          setCurrentInputTime(val);
      }
  };

  const handleFinalize = () => {
      // Initialize Time Boxing
      setPlanningStep('time-boxing');
      setCurrentBoxStageIndex(0);
      setSelectedTimeBoxes([]);
  };

  const toggleTimeBox = (box: string) => {
      if (selectedTimeBoxes.includes(box)) {
          setSelectedTimeBoxes(selectedTimeBoxes.filter(b => b !== box));
      } else {
          setSelectedTimeBoxes([...selectedTimeBoxes, box]);
      }
  };

  const toggleActualHour = (uniqueId: string) => {
      if (selectedActualHours.includes(uniqueId)) {
          setSelectedActualHours(selectedActualHours.filter(h => h !== uniqueId));
      } else {
          setSelectedActualHours([...selectedActualHours, uniqueId]);
      }
  };

  const proceedToPreConfirmation = () => {
      if (selectedTimeBoxes.length === 0) {
          alert("请至少选择一个时间段作为今日规划");
          return;
      }
      setPlanningStep('pre-comparison-confirm');
  };

  const startComparison = () => {
      setPlanningStep('daily-comparison');
      // Initialize actual hours empty
      setSelectedActualHours([]);
  };

  const finishAll = () => {
      alert("太棒了！今日复盘已完成。保持这个节奏！");
      onBack();
  };

  // --- RENDER: INTERMEDIATE STEP (PRE-COMPARISON) ---
  if (planningStep === 'pre-comparison-confirm') {
      const timeBoxConfig = [
          { id: 'morning', label: '早 Morning', icon: Sunrise, color: 'orange' },
          { id: 'afternoon', label: '中 Afternoon', icon: Sun, color: 'sky' },
          { id: 'evening', label: '晚 Evening', icon: Moon, color: 'indigo' }
      ];

      const selectedConfigs = timeBoxConfig.filter(c => selectedTimeBoxes.includes(c.id));

      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 h-full pb-20">
              <div className="text-center mb-8">
                  <h2 className="text-2xl font-black text-slate-800 mb-2">规划确认</h2>
                  <p className="text-slate-500 text-sm">今日专注目标</p>
              </div>

              {/* Selected Boxes Display */}
              <div className="w-full space-y-4 mb-8">
                  {selectedConfigs.map(item => {
                      const activeBg = item.id === 'morning' ? 'bg-orange-50 border-orange-100' :
                                       item.id === 'afternoon' ? 'bg-sky-50 border-sky-100' :
                                       'bg-indigo-50 border-indigo-100';
                      const activeText = item.id === 'morning' ? 'text-orange-600' :
                                         item.id === 'afternoon' ? 'text-sky-600' :
                                         'text-indigo-600';

                      return (
                          <div key={item.id} className={`flex items-center gap-4 p-4 rounded-2xl border ${activeBg} shadow-sm animate-slide-up`}>
                               <div className={`p-2 rounded-full bg-white/80 ${activeText}`}>
                                   <item.icon size={24} />
                               </div>
                               <span className={`text-lg font-bold ${activeText}`}>{item.label}</span>
                               <CheckCircle size={20} className={`ml-auto ${activeText}`} />
                          </div>
                      )
                  })}
              </div>

              {/* Guidance Text */}
              <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 mb-8 max-w-sm">
                  <div className="flex gap-3">
                      <div className="mt-1 text-fuchsia-500"><Sparkles size={20} /></div>
                      <div>
                          <p className="text-sm font-bold text-slate-700 mb-1">即将进入 Done List</p>
                          <p className="text-xs text-slate-500 leading-relaxed">
                              确认后，您将进入执行记录模式。<br/>
                              通过 <span className="font-bold text-slate-700">Done List (实际)</span> 与 <span className="font-bold text-slate-700">Time Box (计划)</span> 的对比，帮助您更直观地复盘今日状态。
                          </p>
                      </div>
                  </div>
              </div>

              {/* Action Buttons */}
              <div className="w-full space-y-3">
                  <button 
                    onClick={startComparison}
                    className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2"
                  >
                      <PlayCircle size={20} />
                      开启 Done List
                  </button>
                  <button onClick={() => setPlanningStep('time-boxing')} className="text-slate-400 text-sm font-bold py-2">
                      返回调整
                  </button>
              </div>
          </div>
      );
  }

  // --- RENDER: TIME BOXING (Planning) ---
  if (planningStep === 'time-boxing') {
      const currentStage = stages[currentBoxStageIndex];
      const stageDuration = Number(estimates[currentStage.id] || 0);
      const currentDay = 1;
      const progressPercent = stageDuration > 0 ? (currentDay / stageDuration) * 100 : 0;
      const startDate = syncedProject ? new Date(syncedProject.startDate) : new Date();
      const displayDate = formatDate(startDate.toISOString());

      return (
        <div className="animate-fade-in h-screen flex flex-col overflow-hidden bg-slate-50">

             {/* Nav Bar */}
             <div className="px-6 py-4 flex justify-between items-center shrink-0">
                <button onClick={() => setPlanningStep('finished')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回概览
                </button>
                <span className="text-xs font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-md">
                    Day {currentDay} / {stageDuration}
                </span>
             </div>

             <div className="flex-1 overflow-y-auto custom-scrollbar px-6 pb-40">

                 {/* Header Card */}
                 <div className="bg-white rounded-3xl p-6 shadow-xl shadow-fuchsia-100 border border-fuchsia-100 mb-8 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-24 h-24 bg-fuchsia-50 rounded-full -mr-10 -mt-10 blur-xl"></div>
                    <div className="relative z-10">
                        <div className="flex items-baseline justify-between mb-1">
                            <span className="text-3xl font-black text-slate-800 tracking-tight">{displayDate.split(' ')[0]}</span>
                            <span className="text-xs font-bold text-fuchsia-500 uppercase tracking-wider">当前阶段</span>
                        </div>
                        <h2 className="text-xl font-bold text-fuchsia-900 mb-2">{currentStage.title}</h2>
                        <div className="bg-slate-100 h-1.5 rounded-full w-full overflow-hidden flex">
                            <div style={{ width: `${progressPercent}%` }} className="bg-fuchsia-500 h-full"></div>
                        </div>
                    </div>
                 </div>

                 {/* Guidance */}
                 <div className="text-center mb-8">
                     <p className="text-sm font-medium text-slate-600 mb-1">选择今天的绘画时段</p>
                     <p className="text-xs text-slate-400 leading-relaxed max-w-xs mx-auto">
                         不做具体的时间刻度安排。<br/>
                         <span className="text-fuchsia-500 font-bold">早、中、晚</span>，你只需决定大致的创作范畴。
                     </p>
                 </div>

                 {/* Timeline & Boxes */}
                 <div className="relative pl-4 space-y-4">
                     {/* Vertical Line */}
                     <div className="absolute left-[27px] top-4 bottom-4 w-0.5 bg-gradient-to-b from-slate-200 via-fuchsia-200 to-slate-200"></div>

                     {/* Nodes */}
                     {[
                         { id: 'morning', label: '早 Morning', icon: Sunrise, color: 'orange', ratio: 'h-24' },
                         { id: 'afternoon', label: '中 Afternoon', icon: Sun, color: 'sky', ratio: 'h-48' },
                         { id: 'evening', label: '晚 Evening', icon: Moon, color: 'indigo', ratio: 'h-36' }
                     ].map((item) => {
                         const isSelected = selectedTimeBoxes.includes(item.id);
                         const activeBg = item.id === 'morning' ? 'bg-gradient-to-r from-orange-50 to-white border-orange-100' :
                                          item.id === 'afternoon' ? 'bg-gradient-to-r from-sky-50 to-white border-sky-100' :
                                          'bg-gradient-to-r from-indigo-50 to-white border-indigo-100';

                         const activeIconBg = item.id === 'morning' ? 'bg-orange-100 text-orange-500' :
                                              item.id === 'afternoon' ? 'bg-sky-100 text-sky-500' :
                                              'bg-indigo-100 text-indigo-500';

                         const activeCheckColor = item.id === 'morning' ? 'text-orange-500' :
                                                  item.id === 'afternoon' ? 'text-sky-500' :
                                                  'text-indigo-500';

                         return (
                             <div 
                                key={item.id}
                                onClick={() => toggleTimeBox(item.id)}
                                className="relative flex items-stretch gap-3 group cursor-pointer transition-all hover:scale-102"
                             >
                                 <div className={`relative z-10 flex flex-col items-center justify-center ${item.id === 'morning' ? 'pt-9' : item.id === 'afternoon' ? 'pt-20' : 'pt-14'}`}>
                                    <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center bg-white transition-colors ${isSelected ? 'border-fuchsia-500 text-fuchsia-500' : 'border-slate-300 text-slate-300'}`}>
                                         <div className={`w-2 h-2 rounded-full ${isSelected ? 'bg-fuchsia-500' : 'bg-transparent'}`}></div>
                                    </div>
                                 </div>
                                 <div className={`flex-1 ${item.ratio} p-4 rounded-2xl border transition-all flex items-center ${isSelected ? activeBg + ' shadow-md' : 'bg-white border-slate-100 text-slate-400'}`}>
                                     <div className="flex items-center justify-between w-full">
                                         <div className="flex items-center gap-2">
                                             <div className={`p-1.5 rounded-full ${isSelected ? activeIconBg : 'bg-slate-50'}`}>
                                                 <item.icon size={16} />
                                             </div>
                                             <span className="text-lg font-bold">{item.label.split(' ')[0]}</span>
                                         </div>
                                         {isSelected && <Check size={16} className={activeCheckColor} />}
                                     </div>
                                 </div>
                             </div>
                         );
                     })}
                 </div>
             </div>

             {/* Bottom Action (Fixed Overlay) */}
             <div className="fixed bottom-0 left-0 w-full bg-gradient-to-t from-white via-white to-transparent pt-10 pb-12 px-6 z-30 pointer-events-none">
                <div className="max-w-lg mx-auto pointer-events-auto">
                    <button 
                        onClick={proceedToPreConfirmation}
                        className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 mb-safe"
                    >
                        确认今日规划
                        <ChevronRight size={20} />
                    </button>
                </div>
             </div>
        </div>
      );
  }

  // --- RENDER: DAILY COMPARISON (Done List Timeline) ---
  if (planningStep === 'daily-comparison') {
      const currentDay = 1;
      // Define ranges
      const isMorning = (h: number) => h >= 9 && h <= 12;
      const isAfternoon = (h: number) => h >= 13 && h <= 17;
      const isEvening = (h: number) => h >= 18 && h <= 27;

      // Check if plan matches
      const getPlanColor = (h: number) => {
          if (isMorning(h) && selectedTimeBoxes.includes('morning')) return 'bg-orange-50/50';
          if (isAfternoon(h) && selectedTimeBoxes.includes('afternoon')) return 'bg-sky-50/50';
          if (isEvening(h) && selectedTimeBoxes.includes('evening')) return 'bg-indigo-50/50';
          return 'bg-white';
      };

      return (
          <div className="animate-fade-in h-screen flex flex-col bg-white">
               {/* Nav */}
               <div className="px-6 py-4 flex justify-between items-start bg-white border-b border-slate-50 shrink-0 z-20">
                   <div>
                       <div className="flex items-center gap-2">
                            <PenTool size={20} className="text-slate-800" />
                            <h2 className="text-xl font-serif font-bold text-slate-800 tracking-tight">Done List</h2>
                       </div>
                       <p className="text-[10px] text-slate-400 mt-1 ml-7">点击时间轴，记录实际专注时段</p>
                   </div>
                   <span className="text-xs font-mono font-medium text-emerald-600 bg-emerald-50 px-3 py-1.5 rounded-full border border-emerald-100">
                       Time: {selectedActualHours.length * 0.5}h
                   </span>
               </div>

               {/* Timeline Container */}
               <div className="flex-1 overflow-y-auto custom-scrollbar pb-32 pt-4">
                   <div className="max-w-lg mx-auto w-full relative">
                        {/* Timeline Vertical Line */}
                        <div className="absolute left-[60px] top-0 bottom-0 w-px bg-slate-100"></div>

                       {timeSlots.map((slot) => {
                           const bgClass = getPlanColor(slot.value);
                           const topId = `${slot.id}-00`;
                           const botId = `${slot.id}-30`;
                           const isTopDone = selectedActualHours.includes(topId);
                           const isBotDone = selectedActualHours.includes(botId);

                           return (
                               <div 
                                   key={slot.id}
                                   className={`flex relative h-20 group ${bgClass}`}
                               >
                                   {/* Time Label */}
                                   <div className="w-[60px] flex-shrink-0 text-right pr-4 pt-4">
                                       <span className="text-xs font-mono text-slate-300">
                                           {slot.label}
                                       </span>
                                       {slot.isNextDay && <div className="text-[8px] text-slate-200">+1</div>}
                                   </div>

                                   {/* Content Area - Split into 2 x 30min slots */}
                                   <div className="flex-1 border-l border-slate-50 relative">
                                        {/* Top Half (00-30) */}
                                        <div 
                                            onClick={() => toggleActualHour(topId)}
                                            className="h-1/2 w-full flex items-center px-4 cursor-pointer hover:bg-black/5 transition-colors border-b border-dashed border-slate-100/50"
                                        >
                                            {isTopDone && (
                                                <Check size={20} className="text-emerald-500 animate-scale-in" strokeWidth={3} />
                                            )}
                                        </div>

                                        {/* Bottom Half (30-60) */}
                                        <div 
                                            onClick={() => toggleActualHour(botId)}
                                            className="h-1/2 w-full flex items-center px-4 cursor-pointer hover:bg-black/5 transition-colors"
                                        >
                                            {isBotDone && (
                                                <Check size={20} className="text-emerald-500 animate-scale-in" strokeWidth={3} />
                                            )}
                                        </div>
                                   </div>
                               </div>
                           );
                       })}

                       {/* Bottom Spacer to match top spacing logic (approx height of 1-2 slots) */}
                       <div className="h-20"></div>
                   </div>
               </div>

               {/* Finish Button */}
               <div className="fixed bottom-0 left-0 w-full bg-gradient-to-t from-white via-white to-transparent pt-4 pb-8 px-6 z-30 pointer-events-none">
                    <div className="max-w-lg mx-auto pointer-events-auto">
                        <button 
                            onClick={finishAll}
                            className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 mb-safe"
                        >
                            <CheckCircle2 size={20} />
                            完成记录
                        </button>
                    </div>
                </div>
          </div>
      );
  }

  // --- RENDER: FINISHED SUMMARY ---
  if (planningStep === 'finished') {
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
              <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-6 shadow-lg shadow-emerald-200">
                  <Check size={40} strokeWidth={3} />
              </div>
              <h2 className="text-2xl font-bold text-slate-800 mb-2">规划已生成</h2>
              <p className="text-slate-500 mb-8">根据您的灵感流，我们计算出了所需天数。</p>

              <div className="w-full bg-white rounded-3xl p-6 shadow-xl shadow-slate-100 border border-slate-100 mb-8">
                  {syncedProject && (
                      <div className="mb-4 pb-4 border-b border-dashed border-slate-200 text-left">
                          <span className="text-[10px] uppercase font-bold text-slate-400">关联项目</span>
                          <div className="flex justify-between items-center mt-1">
                             <p className="font-bold text-slate-800">{syncedProject.clientName}</p>
                             <span className="text-xs bg-slate-100 px-2 py-1 rounded text-slate-600 font-medium">可用 {totalAvailableDays} 天</span>
                          </div>
                      </div>
                  )}
                  {stages.map((stage) => (
                      <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                          <span className="font-medium text-slate-700">{stage.title}</span>
                          <span className="font-bold text-indigo-600">{estimates[stage.id]} 天</span>
                      </div>
                  ))}
                  <div className="mt-4 pt-4 border-t border-slate-100 flex justify-between items-center font-bold text-lg">
                      <span>总计规划</span>
                      <span className={`${isOverBudget ? 'text-rose-600' : 'text-emerald-600'}`}>{currentPlannedDays} 天</span>
                  </div>
                  {isOverBudget && (
                      <p className="text-xs text-rose-500 mt-2 font-medium">注意：规划时间已超出可用工期！</p>
                  )}
              </div>

              <div className="w-full space-y-3">
                  <button 
                    onClick={handleFinalize} 
                    className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2"
                  >
                      <Box size={20} />
                      时间盒子的规划法
                  </button>
                  <button onClick={() => setPlanningStep('time-entry')} className="text-slate-400 text-sm font-bold py-2">
                      返回修改
                  </button>
              </div>
          </div>
      );
  }

  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button 
                onClick={() => {
                    if (planningStep === 'time-entry') setPlanningStep('setup');
                    else onBack();
                }} 
                className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"
            >
                <ArrowLeft size={16} className="mr-1" /> 返回
            </button>
            {planningStep === 'time-entry' && (
                <div className="flex items-center gap-3">
                    {syncedProject && (
                        <div className={`flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded-lg border ${isOverBudget ? 'bg-rose-50 border-rose-100 text-rose-600' : 'bg-emerald-50 border-emerald-100 text-emerald-600'}`}>
                            <Hourglass size={12} />
                            <span>{currentPlannedDays} / {totalAvailableDays} 天</span>
                        </div>
                    )}
                    <span className="text-xs font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-1.5 rounded-lg">
                        逆向规划中...
                    </span>
                </div>
            )}
       </div>

       {planningStep === 'setup' && (
        <div className="mb-6 relative overflow-hidden bg-gradient-to-br from-fuchsia-50 to-rose-50 rounded-3xl border border-fuchsia-100 transition-all">

            {/* Header Content */}
            {!showSyncInput ? (
                <div className="p-6 relative">
                     <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
                        <Sparkles size={80} className="text-fuchsia-500" />
                    </div>
                    <div className="flex justify-between items-start">
                        <div className="flex-1 mr-2">
                            <h2 className="text-2xl font-bold text-fuchsia-900 flex items-center gap-2">
                                <Sparkles size={20} className="text-fuchsia-500" />
                                {syncedProject ? `规划: ${syncedProject.clientName}` : '灵感流 (P人模式)'}
                            </h2>
                            {syncedProject ? (
                                <div className="mt-3 bg-white/60 p-3 rounded-xl border border-fuchsia-100 backdrop-blur-sm shadow-sm">
                                    <div className="flex justify-between items-center mb-2 pb-2 border-b border-fuchsia-100/50">
                                         <span className="text-xs font-bold text-fuchsia-900/60 uppercase">工期预算</span>
                                         <span className="text-lg font-black text-fuchsia-600">{totalAvailableDays} 天</span>
                                    </div>
                                    <div className="flex gap-4">
                                        <div className="flex flex-col">
                                            <span className="text-[10px] text-fuchsia-400 font-bold">开始</span>
                                            <span className="text-xs font-bold text-fuchsia-800">{formatDate(syncedProject.startDate)}</span>
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[10px] text-fuchsia-400 font-bold">截止</span>
                                            <span className="text-xs font-bold text-fuchsia-800">{formatDate(syncedProject.deadline)}</span>
                                        </div>
                                    </div>
                                </div>
                            ) : (
                                <p className="text-xs text-fuchsia-800/60 mt-2 leading-relaxed">
                                    随意<b>拖拽</b>节点调整顺序。
                                </p>
                            )}
                        </div>

                        {!syncedProject && (
                            <button 
                                onClick={() => setShowSyncInput(true)}
                                className="flex items-center gap-1 bg-white/50 hover:bg-white text-fuchsia-700 px-3 py-2 rounded-xl backdrop-blur-sm transition-colors shadow-sm text-xs font-bold whitespace-nowrap"
                                title="同步排单"
                            >
                                <Link size={14} />
                                关联排单
                            </button>
                        )}
                    </div>
                </div>
            ) : (
                <div className="p-4 animate-fade-in">
                    <div className="flex items-center justify-between mb-2">
                         <span className="text-xs font-bold text-fuchsia-800 uppercase">输入排单 ID 同步</span>
                         <button onClick={() => setShowSyncInput(false)}><X size={16} className="text-fuchsia-400" /></button>
                    </div>
                    <div className="flex gap-2">
                        <input 
                            autoFocus
                            type="text" 
                            value={syncId}
                            onChange={(e) => setSyncId(e.target.value)}
                            placeholder="粘贴排单 ID"
                            className="flex-1 text-sm bg-white border border-fuchsia-200 rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-fuchsia-500"
                        />
                        <button 
                            onClick={handleSyncProject}
                            className="bg-fuchsia-600 text-white px-3 py-2 rounded-xl font-bold text-sm"
                        >
                            同步
                        </button>
                    </div>
                </div>
            )}
        </div>
       )}

       <div className="space-y-4 relative">
          {/* Add Button (Hidden in time-entry) */}
          {planningStep === 'setup' && (
             !isAdding ? (
                <div 
                    onClick={() => setIsAdding(true)}
                    className="w-full h-20 border-2 border-dashed border-slate-300 rounded-2xl flex items-center justify-center text-slate-400 cursor-pointer hover:bg-slate-50 hover:border-fuchsia-400 hover:text-fuchsia-500 transition-all active:scale-95 group"
                >
                    <div className="flex flex-col items-center gap-1">
                        <Plus size={24} className="group-hover:scale-110 transition-transform" />
                        <span className="text-xs font-bold uppercase tracking-wider">添加新阶段</span>
                    </div>
                </div>
              ) : (
                <div className="w-full h-20 border-2 border-fuchsia-300 rounded-2xl flex items-center justify-between px-4 bg-white shadow-sm animate-fade-in">
                    <input 
                        autoFocus
                        type="text" 
                        placeholder="输入阶段名称..."
                        value={newStageTitle}
                        onChange={(e) => setNewStageTitle(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()}
                        className="flex-1 bg-transparent text-lg font-medium text-slate-800 outline-none placeholder-slate-300"
                    />
                    <div className="flex gap-2">
                        <button onClick={() => setIsAdding(false)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-full">
                            <X size={20} />
                        </button>
                        <button onClick={handleConfirmAdd} className="p-2 bg-fuchsia-500 text-white rounded-full">
                            <Check size={20} />
                        </button>
                    </div>
                </div>
              )
          )}

          {/* Draggable List */}
          {stages.map((stage, index) => {
            const isActive = index === activeTimeIndex;
            // In setup mode: full width. In time-entry: 40% width and left aligned.
            const containerClass = planningStep === 'setup' 
                ? 'w-full h-24 px-6 border-slate-200 bg-white/50 hover:border-fuchsia-300' 
                : `w-[45%] h-16 px-4 transition-all duration-500 ${isActive ? 'border-fuchsia-500 bg-white shadow-lg scale-105 z-10' : 'border-slate-100 bg-slate-50 opacity-40 grayscale'}`;

            return (
                <div key={stage.id} className="relative flex items-center">
                    {/* The Stage Card */}
                    <div
                        draggable={planningStep === 'setup'}
                        onDragStart={() => handleDragStart(index)}
                        onDragEnter={() => handleDragEnter(index)}
                        onDragEnd={handleDragEnd}
                        onDragEndCapture={handleDragEnd}
                        onDragOver={(e) => e.preventDefault()}
                        onClick={() => {
                            if (planningStep === 'time-entry') {
                                setActiveTimeIndex(index);
                                setCurrentInputTime(estimates[stage.id] || '');
                            }
                        }}
                        className={`
                            relative border rounded-2xl flex items-center 
                            ${containerClass}
                            ${planningStep === 'setup' ? 'cursor-grab active:cursor-grabbing backdrop-blur-sm' : ''}
                            ${planningStep === 'time-entry' ? 'cursor-pointer hover:opacity-80 hover:scale-[1.02]' : ''}
                        `}
                    >
                        {/* Drag Handle (Only Setup) */}
                        {planningStep === 'setup' && (
                            <div className="text-slate-200 mr-4 cursor-grab">
                                <GripVertical size={24} />
                            </div>
                        )}

                        {/* Content */}
                        <div className="flex flex-col truncate">
                            <span className={`font-medium truncate ${planningStep === 'setup' ? 'text-lg text-slate-700' : 'text-sm text-slate-800'}`}>
                                {stage.title}
                            </span>
                            {planningStep === 'time-entry' && estimates[stage.id] && (
                                <span className="text-[10px] text-fuchsia-600 font-bold flex items-center gap-1">
                                    <Clock size={10} /> {estimates[stage.id]} 天
                                </span>
                            )}
                        </div>

                        {/* Delete Action (Only Setup) */}
                        {planningStep === 'setup' && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); deleteStage(index); }}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-200 hover:text-rose-400 p-2"
                            >
                                <X size={16} />
                            </button>
                        )}
                    </div>

                    {/* Time Input Area (Only for Active Item in Time Mode) */}
                    {planningStep === 'time-entry' && isActive && (
                        <div className="flex-1 ml-4 animate-slide-up flex items-center gap-3">
                            <div className="h-0.5 w-4 bg-fuchsia-300"></div>
                            <div className="flex-1">
                                <label className="block text-[10px] font-bold text-fuchsia-500 uppercase mb-1 tracking-wider">
                                    预期耗时 (天)
                                </label>
                                <div className="flex gap-2">
                                    <input 
                                        autoFocus
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="0.5"
                                        value={currentInputTime}
                                        onChange={handleTimeInput}
                                        onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()}
                                        className="w-20 bg-white border-2 border-fuchsia-200 rounded-xl px-3 py-2 text-lg font-bold text-slate-800 outline-none focus:border-fuchsia-500 focus:ring-4 focus:ring-fuchsia-100 transition-all"
                                    />
                                    <button 
                                        onClick={confirmTimeEntry}
                                        disabled={!currentInputTime}
                                        className="bg-slate-900 text-white px-4 rounded-xl disabled:opacity-50 disabled:cursor-not-allowed hover:scale-105 transition-transform flex items-center justify-center"
                                    >
                                        <ArrowUp size={20} />
                                    </button>
                                </div>
                                <p className="text-[10px] text-slate-400 mt-2 leading-tight">
                                    {isOverBudget ? (
                                        <span className="text-rose-500 font-bold">警告：已超出可用工期！</span>
                                    ) : (
                                        <span>当前可用预算: {Math.max(0, totalAvailableDays - currentPlannedDays)} 天</span>
                                    )}
                                </p>
                            </div>
                        </div>
                    )}
                </div>
            );
          })}
       </div>

       {/* Bottom Action Button */}
       {planningStep === 'setup' && (
           <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
               <div className="max-w-lg mx-auto pointer-events-auto">
                   <button 
                     onClick={startConfiguration}
                     className="w-full bg-slate-900 text-white py-4 rounded-2xl shadow-xl shadow-slate-300 font-bold text-lg flex items-center justify-center gap-2 hover:scale-[1.02] active:scale-95 transition-all"
                   >
                       <Check size={20} />
                       已完成配置
                   </button>
               </div>
           </div>
       )}
    </div>
  );
};

