                    >
                        确认今日规划
                        <ChevronRight size={20} />
                    </button>
                </div>
             </div>
        </div>
      );
  }

  // --- RENDER: DAILY COMPARISON (Done List Timeline) ---
  if (planningStep === 'daily-comparison') {
      const baseDate = syncedProject ? new Date(syncedProject.startDate) : new Date();
      const currentDate = addDays(baseDate, currentDateOffset);
      const displayDate = formatDate(currentDate.toISOString());

      // Define ranges
      const isMorning = (h: number) => h >= 9 && h <= 12;
      const isAfternoon = (h: number) => h >= 13 && h <= 17;
      const isEvening = (h: number) => h >= 18 && h <= 27;

      // Check if plan matches
      const getPlanColor = (h: number) => {
          if (isMorning(h) && selectedTimeBoxes.includes('morning')) return 'bg-orange-50';
          if (isAfternoon(h) && selectedTimeBoxes.includes('afternoon')) return 'bg-sky-50';
